import {ToolRegistry} from './registry.js';

describe('ToolRegistry.execute validates input against inputSchema', () => {
  it('rejects input missing a required field without calling executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;

    registry.register(
      {
        name: 'test_tool',
        description: 'Test tool',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
          },
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'success';
      }
    );

    const response = await registry.execute('test_tool', {});

    expect(executorCalls).toBe(0);
    expect(response.result).toContain('location');
    expect(response.result).toMatch(/required/i);
  });
});

